/* 清洗 sid 形态：常被污染成 "sessionid=xxx" / 带引号 / 带分号尾巴 / URL 编码 → 一律会全盘登录失败 */
function fqSidClean(v){
  v=String(v==null?"":v).replace(/^\s+|\s+$/g,"");
  v=v.replace(/^["']+|["']+$/g,"");
  if(v.indexOf("sessionid_ss=")===0) v=v.slice(13);
  else if(v.indexOf("sessionid=")===0) v=v.slice(10);
  var i=v.indexOf(";"); if(i>=0) v=v.slice(0,i);
  if(/%[0-9A-Fa-f]{2}/.test(v)){ try{ v=decodeURIComponent(v) }catch(e){} }
  return v.replace(/\s+$/g,"");
}

