/* 按番茄原始 <p> 拆分，为每一行计算真实段号（修复段号错位：封面图/空段也占位） */

/* 按「段落原文」在正文里反查段号 —— 口径与 fqDpInject 完全一致：
    去除 → 非空行序列 → 若首行为章节标题则剔除 → 剩余非空行的序号（0 起）。
   匹配时对空白做归一化并取前缀，容忍 App 侧拼接文本的细微差异。 */
function fqDpParaOf(txt,ptext){
  try{
    var lines=String(txt==null?"":txt).replace(/\r/g,"").split("\n");
    function ne(a){var r=[];for(var i=0;i<a.length;i++){var x=String(a[i]);if(x.trim()!==""&&!fqImgOnlyLine(x))r.push(i)}return r}
    var idxs=ne(lines);
    if(!idxs.length) return -1;
    if(/^\s*第\s*[0-9零一二三四五六七八九十百千万两]+\s*[章节回]/.test(String(lines[idxs[0]]))){ idxs=idxs.slice(1); }
    var key=String(ptext==null?"":ptext).replace(/\s+/g,"");
    if(!key) return -1;
    if(key.length>30) key=key.slice(0,30);
    for(var k=0;k<idxs.length;k++){
      var t=String(lines[idxs[k]]).replace(/\s+/g,"");
      if(t.indexOf(key)>=0) return k;
    }
    /* 退化匹配：前 12 字符命中即可 */
    var k2=key.slice(0,12);
    if(k2.length>=6){ for(var j=0;j<idxs.length;j++){ if(String(lines[idxs[j]]).replace(/\s+/g,"").indexOf(k2)>=0) return j; } }
  }catch(e){}
  return -1;
}

/* 长按「发段评」入口（legado5 新版 App 读 ruleReview.postUrl；legado4 旧版读 postReviewEntry，两字段兼写）：
   App 注入 java / source / baseUrl / book / chapter / src = 选中段落原文；
   legado5 额外注入 result = App 侧正文段号（0 起，不含章节标题，与 fqDpParaOf 同口径）。
   链路：解析 id → 取正文（优先最近阅读缓存）→ 段号（反查优先，App 段号-1 兜底）→ fqDpClick 打开发段评界面。 */
function fqDpOpen(java,book,chapter,ptext,result){
  var LG=[]; function tip(m){ LG.push(m); }
  function flash(tag){ /* 诊断默认静默：仅失败时给一句简短原因 */
    try{ var _s=LG.join("›"); if(/✗|异常|未打开/.test(_s)) java.toast("发段评失败："+_s.slice(-60)) }catch(e){} }
  try{
    var v=null; try{ v=fqSrc() }catch(e){ v=null; }
    var chUrl=String((chapter&&chapter.url)||"");
    var bkUrl=String((book&&book.bookUrl)||"");
    var ptext=String(ptext==null?"":ptext);
    /* legado5 注入 result=paragraphNum-1：paragraphNum 含标题且从 1 起 → result 是正文【1 基】段号；
       官方/书源口径为正文【0 基】（标题不计，见 fqDpInject），故使用时需 -1。legado4 无此参数(undefined) */
    var appPara=-1; try{ if(result!=null&&result!==""){ var _rn=Number(result); if(!isNaN(_rn)&&_rn>=0) appPara=Math.floor(_rn); } }catch(e){}
    if(appPara>=0) tip("App段号="+appPara);
    if(!chUrl){ LG.push("✗无章节地址"); flash("发段评"); return; }
    var id=fqIdsOf(chUrl,bkUrl,java)||{}, bid=String(id.bid||""), iid=String(id.iid||"");
    if(!bid||!iid){ var id2=fqIdsOf(chUrl,chUrl,java)||{}; if(!bid) bid=String(id2.bid||""); if(!iid) iid=String(id2.iid||""); }
    if(!bid||!iid){ try{ var st0=v?(fqVarGet(v)||{}):{}; if(!bid&&st0.lastBid) bid=String(st0.lastBid); if(!iid&&st0.lastIid) iid=String(st0.lastIid); tip("id走缓存兜底"); }catch(e){} }
    tip("id="+(bid?("b…"+bid.slice(-4)):"无")+"/"+(iid?("i…"+iid.slice(-4)):"无"));
    if(!bid||!iid){ LG.push("✗缺书籍/章节ID"); flash("发段评"); return; }
    var txt="";
    try{ var st=v?(fqVarGet(v)||{}):{}; if(String(st.lastIid)===iid&&st.lastTxt) txt=String(st.lastTxt);
         tip("正文=缓存"+txt.length+(txt?"":("(未命中 last="+(st.lastIid?st.lastIid.slice(-4):"无")+"≠"+iid.slice(-4)+")"))); }catch(e){}
    if(!txt){ try{ txt=String(fqContent(chUrl,bkUrl,java,v)||""); tip("正文=新取"+txt.length); }catch(e2){ txt=""; tip("正文=取失败"); } }
    if(!txt){ try{ var _sv=v||{get:function(){return ""},put:function(){}}; var _cmt=fqContentCm(bid,iid,java,_sv); if(_cmt&&String(_cmt).replace(/\s/g,"")!==""){ txt=String(_cmt); tip("正文=CMG兜底"+txt.length); } }catch(e5){ tip("正文=CMG异常"); } }
    if(!txt){ LG.push("✗取不到正文"); flash("发段评"); return; }
    var para=fqDpParaOf(txt,ptext);
    tip("反查段号="+para);
    /* 口径对齐：反查值与 delta 校准/气泡注入同口径（正文 0 基），优先采用；
       App 段号仅作兜底（-1 转 0 基）与交叉验证。 */
    if(appPara>=0&&para>=0&&appPara!==para){
      if(appPara===para+1) tip("App段号"+appPara+"为1基→0基"+para);
      else tip("App段号"+appPara+"≠反查"+para+"→以反查为准");
    }
    if(para<0&&appPara>=1){ para=appPara-1; tip("反查失败→App段号-1兜底="+para); }
    if(para<0){ tip("段号兜底0"); para=0; }
    if(para>=0){ try{ var _dl=fqDeltaOf(bid,iid,txt,java,v,null,para); var _fix=para-_dl; if(_fix>=0) para=_fix; tip("校准Δ="+_dl+"→段"+para); }catch(e3){ tip("校准跳过"); } }
    var cb64=""; try{ cb64=b64enc(utf8b(ptext)) }catch(e){}
    if(!cb64){ try{ cb64=String(java.base64Encode(ptext)||"") }catch(e){} }
    tip("cb64="+cb64.length);
    flash("发段评·调起");
    var r=fqDpClick(java,bid,iid,String(para),"add",cb64);
    LG.push(r?"✓已打开":"✗未打开(返回"+String(r)+")");
    /* 补写正文缓存：ruleContent 侧因 result 非章节 URL 等场景可能未写，导致下次长按重复取正文 */
    try{ var _cs2=fqVarGet(v)||{}; _cs2.lastBid=bid; _cs2.lastIid=iid; _cs2.lastTxt=txt; fqVarSet(v,_cs2); tip("缓存已补写"+txt.length); }catch(e4){}
    flash("发段评");
  }catch(e){ LG.push("异常:"+String(e).slice(0,90)); flash("发段评"); }
}

