/* 竖版长图限宽。legado 用 paramPattern = \s*,\s*(?=\{) 把「URL」和「option」拆开，
   所以 option 必须写在 src 属性值内部、以 ,{ 开头；引号要用 &quot; 转义，
   直接写 " 会提前闭合 HTML 属性，jsoup 解析时 option 就丢了。
   目的：卷首插画这类高瘦长图按屏宽铺满后高度超过一页，排版只能整块挪到下一页，
   上一页只剩标题、大片留白。按高宽比限宽 → 高度同比例变小 → 能和标题同页。
   只动竖图（r>=1.3），横图/方图原样返回，避免影响本来就正常的图。 */
function fqImgTag(tag){
  try{
    var m=tag.match(/(<img\b[^>]*?\bsrc\s*=\s*)(["'])([\s\S]*?)\2/i);
    if(!m) return tag;
    if(/,\s*\{/.test(m[3])) return tag;                          /* src 里已有 option，别重复加 */
    var w=parseFloat((tag.match(/img-width\s*=\s*"([^"]*)"/i)||[])[1]||"0");
    var h=parseFloat((tag.match(/img-height\s*=\s*"([^"]*)"/i)||[])[1]||"0");
    if(!(w>0&&h>0)) return tag;
    /* 只给超长竖图（h/w >= 1.8）等比缩窄到 95%；
       横图、方图、普通竖图一律不动。
       两个坑：① 取值要用 parseFloat 且允许任意字符 —— 番茄有的书是 img-width="692"，
       有的是 img-width="390px"（带单位），只匹配纯数字会让后者失效；
       ② option 必须裸双引号 —— 写 &quot; 时 GSON 解析失败、option 被整体丢弃。 */
    if(h/w < 1.8) return tag;
    var opt=',{"width":"95%"}';
    return tag.replace(m[0], m[1]+m[2]+m[3]+opt+m[2]);
  }catch(e){ return tag; }
