  while((m=re.exec(s))!==null){
    if(/^<img/i.test(m[0])){
      out.push(fqImgTag(m[0]));
    }else{
      var body=m[1]||"";
      var imgs=body.match(/<img\b[^>]*>/gi)||[];
      var txt=body.replace(/<[^>]*>/g,"").replace(/&nbsp;/g," ").trim();
      if(imgs.length) out.push((txt||"")+imgs.join(""));
